# running_sum :: [1, 2, 3, 4, 5]
def running_sum(xs):
    out = []
    s = 0
    for x in xs:
        s += x
        out.append(s)
    return out

if __name__ == '__main__':
    print(running_sum([1, 2, 3, 4, 5]))

